package com.example.nailsalon.config;
import com.example.nailsalon.security.JwtFilter; import org.springframework.context.annotation.*; import org.springframework.security.config.annotation.web.builders.HttpSecurity; import org.springframework.security.config.http.SessionCreationPolicy; import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.security.web.SecurityFilterChain; import org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter;
@Configuration public class SecurityConfig { @Bean PasswordEncoder passwordEncoder(){return new BCryptPasswordEncoder();} @Bean SecurityFilterChain filterChain(HttpSecurity h,JwtFilter f)throws Exception{return h.csrf(c->c.disable()).headers(x->x.frameOptions(y->y.sameOrigin())).sessionManagement(s->s.sessionCreationPolicy(SessionCreationPolicy.STATELESS)).authorizeHttpRequests(a->a.requestMatchers("/swagger-ui.html","/swagger-ui/**","/v3/api-docs/**","/h2-console/**","/api/auth/**").permitAll().requestMatchers("/api/**").authenticated().anyRequest().permitAll()).addFilterBefore(f,UsernamePasswordAuthenticationFilter.class).build();} }
